if(!$USER->IsAuthorized()||!$USER->IsAdmin()){http_response_code(403);header('Content-Type: text/html; charset=UTF-8');echo '<!doctype html><html lang="ru"><meta charset="utf-8"><h1>Нужен вход администратора</h1><a href="/bitrix/admin/">Войти в Битрикс</a></html>';exit;}
$h=static function($v){return htmlspecialcharsbx((string)$v);};$messages=[];$error='';$done=false;$siteId=defined('SITE_ID')?(string)SITE_ID:'';$site=$siteId!==''?CSite::GetByID($siteId)->Fetch():false;
$definitions=['McPodeluClients'=>['table'=>'mc_podelu_clients','fields'=>['UF_NAME'=>['string','Название клиента',true,150],'UF_SITE'=>['string','Сайт клиента',false,255],'UF_COMMENT'=>['string','Внутренняя заметка',false,3000],'UF_ACTIVE'=>['boolean','Активный клиент',false,1],'UF_CREATED_AT'=>['datetime','Дата создания',false,0],'UF_CREATED_BY'=>['integer','ID создавшего пользователя',false,0],'UF_XML_ID'=>['string','Внешний идентификатор',true,64]]],'McPodeluDirections'=>['table'=>'mc_podelu_directions','fields'=>['UF_NAME'=>['string','Название направления',true,100],'UF_ACTIVE'=>['boolean','Активно',false,1],'UF_XML_ID'=>['string','Внешний идентификатор',true,64]]],'McPodeluPackages'=>['table'=>'mc_podelu_packages','fields'=>['UF_CLIENT'=>['integer','ID клиента',true,0],'UF_MONTH'=>['string','Первый месяц / месяц разового пакета',true,7],'UF_NAME'=>['string','Базовое название пакета',true,150],'UF_MINUTES'=>['integer','Базовый лимит в минутах',true,0],'UF_DIRECTION_IDS'=>['string','Базовые ID направлений JSON',true,2000],'UF_XML_ID'=>['string','Внешний идентификатор',true,64],'UF_CREATED_AT'=>['datetime','Дата создания',false,0],'UF_CREATED_BY'=>['integer','ID создавшего пользователя',false,0],'UF_REPEAT'=>['boolean','Повторять каждый месяц',false,0],'UF_END_MONTH'=>['string','Последний месяц включительно',false,7]]],'McPodeluPackageRules'=>['table'=>'mc_podelu_package_rules','fields'=>['UF_PACKAGE'=>['integer','ID пакета',true,0],'UF_MONTH'=>['string','Месяц действия YYYY-MM',true,7],'UF_SCOPE'=>['string','Режим one / from',true,10],'UF_NAME'=>['string','Название по этим условиям',true,150],'UF_MINUTES'=>['integer','Лимит в минутах',true,0],'UF_DIRECTION_IDS'=>['string','ID направлений JSON',true,2000],'UF_CREATED_AT'=>['datetime','Дата создания / изменения',false,0],'UF_CREATED_BY'=>['integer','Пользователь',false,0]]]];
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!check_bitrix_sessid())$error='Сессия истекла. Обновите страницу.';
 else try{
  if(!$site)throw new RuntimeException('Текущий сайт не определён.');
  foreach(['/local/templates/podelu/header.php','/local/templates/podelu/app.css','/local/components/markitan/podelu/lib/Repository.php','/local/components/markitan/podelu/lib/PackagePolicy.php','/local/components/markitan/podelu/templates/.default/template.php'] as $file)if(!is_file($_SERVER['DOCUMENT_ROOT'].$file))throw new RuntimeException('Не найден '.$file.'. Загрузите весь комплект.');
  if(!Loader::includeModule('highloadblock'))throw new RuntimeException('Нет модуля Highload-блоков.');
  $blockIds=[];
  foreach($definitions as $name=>$def){
   $block=HighloadBlockTable::getList(['filter'=>['=NAME'=>$name],'limit'=>1])->fetch();$byTable=HighloadBlockTable::getList(['filter'=>['=TABLE_NAME'=>$def['table']],'limit'=>1])->fetch();
   if(($block&&$block['TABLE_NAME']!==$def['table'])||($byTable&&$byTable['NAME']!==$name))throw new RuntimeException('Конфликт таблицы '.$name.'. Существующие записи не удалялись.');
   if($block){$id=(int)$block['ID'];$messages[]=$name.': найден блок #'.$id.'.';}
   else{$r=HighloadBlockTable::add(['NAME'=>$name,'TABLE_NAME'=>$def['table']]);if(!$r->isSuccess())throw new RuntimeException(implode('; ',$r->getErrorMessages()));$id=(int)$r->getId();$messages[]=$name.': создан блок #'.$id.'.';}
   $blockIds[$name]=$id;$sort=100;
   foreach($def['fields'] as $field=>$f){
    $old=CUserTypeEntity::GetList([],['ENTITY_ID'=>'HLBLOCK_'.$id,'FIELD_NAME'=>$field])->Fetch();
    if($old){if($old['USER_TYPE_ID']!==$f[0]||$old['MULTIPLE']==='Y')throw new RuntimeException('Несовместимое поле '.$name.'.'.$field.'. Автоматическое изменение типа запрещено.');$sort+=10;continue;}
    $settings=[];if($f[0]==='string')$settings=['SIZE'=>40,'ROWS'=>in_array($field,['UF_COMMENT','UF_DIRECTION_IDS'],true)?4:1,'MAX_LENGTH'=>$f[3],'MIN_LENGTH'=>0,'DEFAULT_VALUE'=>''];
    if($f[0]==='boolean')$settings=['DEFAULT_VALUE'=>$f[3],'DISPLAY'=>'CHECKBOX'];
    $uf=new CUserTypeEntity();$newId=$uf->Add(['ENTITY_ID'=>'HLBLOCK_'.$id,'FIELD_NAME'=>$field,'USER_TYPE_ID'=>$f[0],'XML_ID'=>'MC_PODELU_'.$field,'SORT'=>$sort,'MULTIPLE'=>'N','MANDATORY'=>$f[2]?'Y':'N','SHOW_FILTER'=>'I','SHOW_IN_LIST'=>'Y','EDIT_IN_LIST'=>'Y','IS_SEARCHABLE'=>'N','SETTINGS'=>$settings,'EDIT_FORM_LABEL'=>['ru'=>$f[1],'en'=>$f[1]],'LIST_COLUMN_LABEL'=>['ru'=>$f[1],'en'=>$f[1]],'LIST_FILTER_LABEL'=>['ru'=>$f[1],'en'=>$f[1]]]);
    if(!$newId){$ex=$APPLICATION->GetException();throw new RuntimeException('Не создано '.$field.($ex?': '.$ex->GetString():'.'));}$sort+=10;$messages[]='Добавлено '.$name.'.'.$field.'.';
   }
  }
  // Для транзакционных изменений условий нужны InnoDB-таблицы. Не меняем движок автоматически.
  foreach(['mc_podelu_packages','mc_podelu_package_rules'] as $table){$status=Application::getConnection()->query("SHOW TABLE STATUS WHERE Name = '".$table."'")->fetch();if(!$status||strtolower((string)$status['Engine'])!=='innodb')throw new RuntimeException('Таблица '.$table.' должна использовать InnoDB. Обратитесь к администратору хостинга; данные не очищались.');}
  $hl=HighloadBlockTable::getById($blockIds['McPodeluDirections'])->fetch();$dc=HighloadBlockTable::compileEntity($hl)->getDataClass();
  foreach(['MC_SITE'=>'Сайт','MC_1C'=>'1С'] as $xml=>$title){$exists=$dc::getList(['filter'=>['LOGIC'=>'OR',['=UF_XML_ID'=>$xml],['=UF_NAME'=>$title]],'limit'=>1])->fetch();if(!$exists){$r=$dc::add(['UF_NAME'=>$title,'UF_ACTIVE'=>1,'UF_XML_ID'=>$xml]);if(!$r->isSuccess())throw new RuntimeException('Не создано направление '.$title.': '.implode('; ',$r->getErrorMessages()));$messages[]='Добавлено направление «'.$title.'».';}}
  foreach(['McPodeluClients'=>'clients_hl_id','McPodeluDirections'=>'directions_hl_id','McPodeluPackages'=>'packages_hl_id','McPodeluPackageRules'=>'rules_hl_id'] as $name=>$key)Option::set('markitan.podelu',$key,(string)$blockIds[$name]);
  if(isset($_POST['assign_template'])&&$_POST['assign_template']==='Y'){
   $key='previous_templates_'.$siteId;if(Option::get('markitan.podelu',$key,'')===''){$old=[];$rs=CSite::GetTemplateList($siteId);while($r=$rs->Fetch())$old[]=['TEMPLATE'=>$r['TEMPLATE'],'SORT'=>(int)$r['SORT'],'CONDITION'=>$r['CONDITION']];Option::set('markitan.podelu',$key,json_encode($old,JSON_UNESCAPED_UNICODE));}
   $manager=new CSite();if(!$manager->Update($siteId,['TEMPLATE'=>[['TEMPLATE'=>'podelu','SORT'=>1,'CONDITION'=>'']]]))throw new RuntimeException('Шаблон не назначен: '.$manager->LAST_ERROR);
   $messages[]='Текущему сайту '.$siteId.' назначен шаблон podelu.';
  }
  Option::set('markitan.podelu','schema_version','1.4.0');$messages[]='Клиенты и пакеты сохранены. Существующие пакеты остаются разовыми. Повторение включается вручную в карточке пакета.';$done=true;
 }catch(Throwable $e){$error=$e->getMessage();AddMessage2Log($error,'markitan.podelu.install');}
